enum Node {
    File { bytes: u64 },
    Dir { children: Vec<Node> },
}

impl Node {
    fn size(&self) -> u64 {
        match self {
            Node::File { bytes } => *bytes,
            Node::Dir { children } => children.iter().map(Node::size).sum(),
        }
    }
}

