trait Component { fn size(&self) -> u64; }

struct File { bytes: u64 }
impl Component for File { fn size(&self) -> u64 { self.bytes } }

struct Dir { children: Vec<Box<dyn Component>> }
impl Dir {
    fn add(&mut self, child: impl Component + 'static) { self.children.push(Box::new(child)); }
}
impl Component for Dir {
    fn size(&self) -> u64 { self.children.iter().map(|c| c.size()).sum() }
}
